#[derive(Debug, Clone, Copy)]
enum ResponseStyle {
    Minimal,
    Echo,
    Full,
}


/// Interpret bytes as LE/BE f32 sequences for pose RE (log only).
fn float_preview(data: &[u8], max_floats: usize) -> String {
    let n = std::cmp::min(data.len() / 4, max_floats);
    if n == 0 {
        return String::from("(no floats)");
    }
    let mut le = Vec::with_capacity(n);
    let mut be = Vec::with_capacity(n);
    for i in 0..n {
        let b = &data[i * 4..i * 4 + 4];
        le.push(f32::from_le_bytes([b[0], b[1], b[2], b[3]]));
        be.push(f32::from_be_bytes([b[0], b[1], b[2], b[3]]));
    }
    format!(
        "LE[{}] BE[{}]",
        le.iter().map(|v| format!("{:.4}", v)).collect::<Vec<_>>().join(","),
        be.iter().map(|v| format!("{:.4}", v)).collect::<Vec<_>>().join(",")
    )
}

/// Try to peel StreamFlowCtrl 7-byte header:
///   u32 BE body_len | u8 channel | u16 BE stream_seq | body...
fn peel_stream_header(payload: &[u8]) -> Option<(u8, u16, &[u8])> {
    if payload.len() < 7 {
        return None;
    }
    let body_len = u32::from_be_bytes([payload[0], payload[1], payload[2], payload[3]]) as usize;
    let channel = payload[4];
    let stream_seq = u16::from_be_bytes([payload[5], payload[6]]);
    if body_len + 7 > payload.len() {
        return None;
    }
    // Heuristic: channel 0..7 and body_len plausible
    if channel > 7 || body_len == 0 || body_len > 65507 {
        return None;
    }
    Some((channel, stream_seq, &payload[7..7 + body_len]))
}

fn make_hello_json(style: ResponseStyle) -> String {
    match style {
        ResponseStyle::Minimal => {
            r#"{"ProtocolVersion":1,"ProtocolMinVersion":1,"MaxDatagramSize":65507,"DatagramSize":65507,"Port":1235,"DeviceID":"relivevr-linux-probe","ServerName":"ReliveVR Linux Probe"}"#.to_string()
        }
        ResponseStyle::Echo => {
            r#"{"DeviceID":"relivevr-linux-probe","MaxDatagramSize":65507,"DatagramSize":65507,"Port":1235,"Options":{"DeviceType":{"Type":"string","Val":"PC"}},"ProtocolMinVersion":1,"ProtocolVersion":1,"ServerName":"ReliveVR Linux Probe"}"#.to_string()
        }
        // Match Windows ReliveVR HelloResponse from live pcap (2026-10-09):
        // ChannelsSupported[4]=true is DeviceEvent/pose channel; VideoCodecs hevc.
        ResponseStyle::Full => {
            r#"{"ChannelsSupported":[true,true,false,false,true,false,false,false,false],"DatagramSize":65507,"MaxDatagramSize":65507,"Options":{"EncoderSize":[1440,1440],"HorizontalFOV":1.7453292608261108,"KeyboardPresent":true,"Microphone":false,"MousePresent":true,"TouchScreenPresent":false,"VerticalFOV":1.7453292608261108,"VideoCodecs":["hevc","avc"]},"Port":1235,"ProtocolMinVersion":1,"ProtocolVersion":1,"ServerName":"ReliveVR Linux Probe","Transports":["UDP"]}"#.to_string()
        }
    }
}

fn make_typed_json_packet(seq: u16, type_byte: u8, json: &str) -> Vec<u8> {
    let mut payload = Vec::with_capacity(1 + json.len());
    payload.push(type_byte);
    payload.extend_from_slice(json.as_bytes());
    FragmentHeader::build_single(seq, 0, &payload)
}

/// Fragment → [stream 7B header][type][json]  (post-connect channelled path)
#[allow(dead_code)]
fn make_stream_json_packet(
    frag_seq: u16,
    stream_seq: u16,
    channel: u8,
    type_byte: u8,
    json: &str,
) -> Vec<u8> {
    let mut body = Vec::with_capacity(1 + json.len());
    body.push(type_byte);
    body.extend_from_slice(json.as_bytes());
    let stream = make_stream_message(channel, stream_seq, &body);
    FragmentHeader::build_single(frag_seq, 0, &stream)
}

/// VideoInit fields from VideoInit::FromJSON: Width, Height, CodecID, NonLinearScaling.
fn make_video_init_json(width: u32, height: u32, codec: &str, nls: bool) -> String {
    // Shape from Windows pcap VideoInit (S→C after StartRequest):
    // BitDepth, CodecID, Height, ID, NonLinearScaling, Viewport, Width
    // (+ optional HEVC/AVC parameter-set NALs after JSON — not required for pose).
    // Field order/names match Windows pcap #7 (ID is session-ish; use non-zero).
    format!(
        r#"{{"BitDepth":8,"CodecID":"{}","Height":{},"ID":{},"NonLinearScaling":{},"Viewport":[0,0,{},{}],"Width":{}}}"#,
        codec,
        height,
        1u64, // Windows used a large timestamp-like ID; 1 is accepted in tests
        if nls { "true" } else { "false" },
        width,
        height,
        width
    )
}

/// Windows-style VideoInit: flags=1, body = pure JSON (no type byte) [+ optional NALs].
/// Live pcap #7: header ends …01 00 then `{"BitDepth":…}` then codec config NALs.
fn make_windows_video_init_packet(seq: u16, json: &str, trailer: &[u8]) -> Vec<u8> {
    // Pcap #7 body: type0 + JSON + NUL + codec config NALs (strlen then binary).
    // Wire: flags=1, then 0x00, `{"BitDepth":…}`, 0x00, Annex-B VPS/SPS/PPS.
    let mut body = Vec::with_capacity(1 + json.len() + 1 + trailer.len());
    body.push(0u8);
    body.extend_from_slice(json.as_bytes());
    body.push(0u8); // NUL after JSON (Windows pcap)
    body.extend_from_slice(trailer);
    FragmentHeader::build_single(seq, 1, &body)
}

/// Pull Annex-B SPS (NAL 7) + PPS (NAL 8) from an IDR bitstream for VideoInit trailer.
fn h264_param_sets(idr: &[u8]) -> Vec<u8> {
    let mut out = Vec::new();
    let mut i = 0;
    while i + 4 < idr.len() {
        // start code 00 00 00 01 or 00 00 01
        let sc = if idr[i..].starts_with(&[0, 0, 0, 1]) {
            4
        } else if idr[i..].starts_with(&[0, 0, 1]) {
            3
        } else {
            i += 1;
            continue;
        };
        let nal_start = i + sc;
        if nal_start >= idr.len() {
            break;
        }
        let nal_type = idr[nal_start] & 0x1f;
        // find next start code
        let mut j = nal_start + 1;
        while j + 3 < idr.len() {
            if idr[j..].starts_with(&[0, 0, 0, 1]) || idr[j..].starts_with(&[0, 0, 1]) {
                break;
            }
            j += 1;
        }
        if nal_type == 7 || nal_type == 8 {
            out.extend_from_slice(&idr[i..j]);
        }
        i = j;
        if nal_type == 5 {
            break; // past param sets
        }
    }
    out
}


/// Best-effort parse of StartRequest fields we care about.

/// Video frame body for Motor::OnFrameReceived:
///   [1][VideoData JSON\0][H.264 Annex-B NALs]
/// Fragment flags byte = channel (1 = video).
fn make_video_data_json(frame_num: u64, frm_type: u32, cmp_size: u32, pts_us: u64) -> String {
    // PTS in microseconds — prefer wall-clock from stream start to avoid DisplayPipeline lag.
    format!(
        r#"{{"ptsSensor":{pts},"ptsServerLat":0,"ptsEncoderLat":0,"pts":{pts},"cmpFrmSize":{cmp},"frmType":{ft},"encType":0,"ptsSend":{pts},"frameNum":{fn}}}"#,
        pts = pts_us,
        cmp = cmp_size,
        ft = frm_type,
        fn = frame_num,
    )
}

